import{_t as e,it as t,n,rt as r}from"./chunks/framework.BzA9dy5I.js";var i=JSON.parse(`{"title":"Conectar tu IA","description":"","frontmatter":{},"headers":[],"relativePath":"guia/integraciones.md","filePath":"guia/integraciones.md"}`),a={name:`guia/integraciones.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="conectar-tu-ia" tabindex="-1">Conectar tu IA <a class="header-anchor" href="#conectar-tu-ia" aria-label="Permalink to “Conectar tu IA”">​</a></h1><p>Hyperion mantiene el mismo proceso independientemente de la herramienta que realiza el trabajo. La conexión local aporta las herramientas o instrucciones necesarias para crear y actualizar el flujo.</p><h2 id="camino-recomendado" tabindex="-1">Camino recomendado <a class="header-anchor" href="#camino-recomendado" aria-label="Permalink to “Camino recomendado”">​</a></h2><p>Instala Desktop y abre <strong>Hyperion → Conectar con mi IA</strong>. El asistente configura:</p><table tabindex="0"><thead><tr><th>Herramienta</th><th>Conexión</th></tr></thead><tbody><tr><td>Codex</td><td>Servidor MCP local</td></tr><tr><td>Cursor</td><td>Servidor MCP local</td></tr><tr><td>Claude Desktop</td><td>Servidor MCP local</td></tr><tr><td>Claude Code</td><td>Skill administrada con acceso al runtime de Desktop</td></tr></tbody></table><p>Después reinicia la herramienta y abre un chat nuevo. Las integraciones existentes no se sobreescriben a ciegas: el asistente informa conflictos y respalda los archivos que modifica.</p><p>Una conexión instalada no garantiza que un chat ya abierto haya cargado las herramientas. Tampoco basta mencionar «Hyperion» en una aplicación sin integración.</p><h2 id="si-no-reconoce-hyperion" tabindex="-1">Si no reconoce Hyperion <a class="header-anchor" href="#si-no-reconoce-hyperion" aria-label="Permalink to “Si no reconoce Hyperion”">​</a></h2><ol><li>Comprueba que elegiste la herramienta correcta en el asistente.</li><li>Reinicia esa herramienta y abre un chat nuevo.</li><li>Pide «Usa Hyperion para…» con un objetivo concreto.</li><li>Si sigue fallando, revisa el error del asistente o del servidor MCP de tu herramienta.</li></ol><p>No compartas archivos de credenciales ni tokens al reportar un error.</p><h2 id="si-el-flujo-no-sigue-tras-guardar" tabindex="-1">Si el flujo no sigue tras guardar <a class="header-anchor" href="#si-el-flujo-no-sigue-tras-guardar" aria-label="Permalink to “Si el flujo no sigue tras guardar”">​</a></h2><p>Tu respuesta se guarda localmente. El agente puede recibirla mientras espera con la integración; un chat que terminó necesita un nuevo mensaje. Usa <strong>Copiar continuación</strong> en el canvas y envíalo en el chat. <a href="./usar-el-flujo.html#retomar-el-trabajo">Más sobre la continuidad</a>.</p><h2 id="otras-aplicaciones" tabindex="-1">Otras aplicaciones <a class="header-anchor" href="#otras-aplicaciones" aria-label="Permalink to “Otras aplicaciones”">​</a></h2><p>Un cliente compatible puede usar el servidor MCP, la CLI o la API local. Debe aportar un agente que planifique y ejecute: Hyperion no incluye un modelo de IA ni interpreta peticiones por sí solo.</p><p>La edición actual comunica aplicaciones en el mismo equipo. No expongas el servicio local como un servidor remoto para conectar otros equipos.</p><p>Para integradores: <a href="https://github.com/0vas/hiperion/blob/main/docs/conexion.md" target="_blank" rel="noreferrer">conexión técnica</a>, <a href="https://github.com/0vas/hiperion/blob/main/docs/protocol.md" target="_blank" rel="noreferrer">protocolo</a> y <a href="https://github.com/0vas/hiperion/blob/main/docs/process-contract.md" target="_blank" rel="noreferrer">contrato del proceso</a>.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};